// Click handler for clickable records in EAV views
document.addEventListener('DOMContentLoaded', () => {
    // Use event delegation for dynamically loaded content
    document.body.addEventListener('click', (e) => {
        const clickable = e.target.closest('.clickable-record');
        if (!clickable) return;

        // Ignore if clicking on buttons or links (they have their own navigation)
        if (e.target.closest('.btn, a, button')) return;

        const url = clickable.dataset.recordUrl;
        if (url) {
            window.location.href = url;
        }
    });
});
